import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { SessionListItem } from '../../interfaces/toolbar.interface';

@Injectable({
  providedIn: 'root'
})
export class ToolbarService {

  constructor(private http: HttpClient) { }



  async getSessionList(nCaseid: string, nUserid: string, cType?: string): Promise<SessionListItem[]> {
    let params = new HttpParams().set('nCaseid', nCaseid);
    params = params.set('nUserid', nUserid);

    if (cType) {
      params = params.set('cType', cType);
    }

    try {
      const res: SessionListItem[] = await firstValueFrom(
        this.http.get<SessionListItem[]>(
          `${environment.cloudUrl2}${environment.realtimeserive}/session/getsessionsbycaseid`,
          { params: params }
        )
      );
      if (!res.length) {
        return [];
      }

      return res;

    } catch (error) {
      console.error(error)
      return [];
    }
  }

}
