import { Injectable } from '@angular/core';
import { feeds } from '@rt/interfaces';
import { finalFeedData } from '@rt/interfaces';
import { RenderOptions, DEFAULT_RENDER_OPTIONS } from './render-options.interface';

@Injectable({
  providedIn: 'root'
})
export class TranscriptRendererService {

  /**
   * Converts structured feed data into semantic HTML string.
   * This is the canonical renderer — its output is what gets persisted
   * and used as the source-of-truth for published transcripts.
   */
  renderToHtml(pages: feeds[], options: Partial<RenderOptions> = {}): string {
    const opts: RenderOptions = { ...DEFAULT_RENDER_OPTIONS, ...options };
    const pagesHtml = this.renderPages(pages, opts);

    if (opts.cssMode === 'inline') {
      return this.wrapWithInlineStyles(pagesHtml);
    }

    return this.wrapWithLinkedStyles(pagesHtml);
  }

  /**
   * Renders all pages to HTML
   */
  private renderPages(pages: feeds[], opts: RenderOptions): string {
    let html = '';

    for (const page of pages) {
      if (opts.pageRange) {
        if (page.page < opts.pageRange.start || page.page > opts.pageRange.end) {
          continue;
        }
      }
      html += this.renderPage(page, opts);
    }

    return html;
  }

  /**
   * Renders a single page with its lines
   */
  private renderPage(page: feeds, opts: RenderOptions): string {
    const pageBreakClass = opts.includePageBreaks ? ' transcript-page-break' : '';
    let html = `<div class="transcript-page${pageBreakClass}" data-page="${page.page}">\n`;
    html += `  <div class="transcript-page-header">Page ${page.page}</div>\n`;

    if (page.data && page.data.length) {
      for (const line of page.data) {
        html += this.renderLine(line, page.page, opts);
      }
    }

    html += `</div>\n`;
    return html;
  }

  /**
   * Renders a single transcript line with semantic classes
   */
  private renderLine(line: finalFeedData, pageno: number, opts: RenderOptions): string {
    const classes = this.getLineClasses(line);
    const dataAttrs = this.getLineDataAttributes(line, pageno);

    let html = `  <div class="transcript-line ${classes.join(' ')}" ${dataAttrs}>\n`;

    // Line number
    if (opts.includeLineNumbers) {
      const lineNumDisplay = line.lineIndex === 1 ? `${pageno}.${line.lineIndex}` : `${line.lineIndex}`;
      html += `    <span class="line-number">${this.escapeHtml(lineNumDisplay)}</span>\n`;
    }

    // Timestamp
    if (opts.includeTimestamps && line.time) {
      html += `    <span class="timestamp">${this.escapeHtml(this.formatTimestamp(line.time))}</span>\n`;
    }

    // Text content
    const textContent = line.lines ? line.lines.join(' ') : '';
    const textWithLinks = this.processLinks(textContent, line.links);
    html += `    <span class="line-text">${textWithLinks}</span>\n`;

    html += `  </div>\n`;
    return html;
  }

  /**
   * Determines CSS classes for a line based on its metadata
   */
  private getLineClasses(line: finalFeedData): string[] {
    const classes: string[] = [];

    if (line.formate === 'QES' || line.formate === 'QES-CONTINUE') {
      classes.push('question-block');
    }

    if (line.formate === 'PRNTH') {
      classes.push('parenthetical');
    }

    if (line.formate === 'FL') {
      classes.push('first-line');
    }

    if (line.isBold) {
      classes.push('is-bold');
    }

    if (line.nHid) {
      classes.push('highlighted');
    }

    return classes;
  }

  /**
   * Generates data-* attributes for annotation anchoring
   */
  private getLineDataAttributes(line: finalFeedData, pageno: number): string {
    const attrs: string[] = [];

    attrs.push(`data-line="${line.lineIndex}"`);
    attrs.push(`data-page="${pageno}"`);

    if (line.unicid) {
      attrs.push(`data-identity="${this.escapeAttr(line.unicid)}"`);
    }

    if (line.oPage != null) {
      attrs.push(`data-opage="${line.oPage}"`);
    }

    if (line.oLine != null) {
      attrs.push(`data-oline="${line.oLine}"`);
    }

    if (line.nHid) {
      attrs.push(`data-hid="${this.escapeAttr(line.nHid)}"`);
    }

    if (line.time) {
      attrs.push(`data-time="${this.escapeAttr(line.time)}"`);
    }

    return attrs.join(' ');
  }

  /**
   * Formats timestamp from raw format (e.g., HH:MM:SS:MS) to display format
   */
  private formatTimestamp(time: string): string {
    if (!time) return '';
    // Strip milliseconds if present (HH:MM:SS:MS → HH:MM:SS)
    const parts = time.split(':');
    if (parts.length >= 3) {
      return parts.slice(0, 3).join(':');
    }
    return time;
  }

  /**
   * Processes hyperlinks found in a line's text
   */
  private processLinks(text: string, links?: string[]): string {
    let escaped = this.escapeHtml(text);
    if (links && links.length > 0) {
      for (const link of links) {
        const escapedLink = this.escapeHtml(link);
        escaped = escaped.replace(
          escapedLink,
          `<a class="transcript-link" href="${this.escapeAttr(link)}" target="_blank">${escapedLink}</a>`
        );
      }
    }
    return escaped;
  }

  /**
   * Wraps rendered pages HTML with linked stylesheet reference
   */
  private wrapWithLinkedStyles(pagesHtml: string): string {
    return `<div class="transcript-document">\n${pagesHtml}</div>`;
  }

  /**
   * Wraps rendered pages HTML with inline styles for self-contained output
   * (used for PDF generation and email/export scenarios)
   */
  private wrapWithInlineStyles(pagesHtml: string): string {
    return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Transcript</title>
  <style>
    ${INLINE_CSS}
  </style>
</head>
<body>
  <div class="transcript-document">
    ${pagesHtml}
  </div>
</body>
</html>`;
  }

  /**
   * Escapes HTML special characters in text content
   */
  private escapeHtml(text: string): string {
    if (!text) return '';
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  /**
   * Escapes attribute values
   */
  private escapeAttr(value: string): string {
    if (!value) return '';
    return value
      .replace(/&/g, '&amp;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
  }
}

/**
 * Inline CSS for self-contained HTML output.
 * Mirrors the semantic classes from transcript.css
 */
const INLINE_CSS = `
  * { margin: 0; padding: 0; box-sizing: border-box; }

  .transcript-document {
    font-family: 'Courier New', Courier, monospace;
    font-size: 15px;
    line-height: 1.5;
    color: #1a1a1a;
    background: #fff;
  }

  .transcript-page {
    position: relative;
    padding: 16px 40px 24px 40px;
    min-width: 956px;
    max-width: fit-content;
    width: fit-content;
    background: #fff;
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }

  .transcript-page-break {
    page-break-after: always;
    break-after: page;
  }

  .transcript-page-header {
    background: #737373;
    color: #fff;
    font-size: 12px;
    padding: 6px 10px;
    margin-bottom: 24px;
    height: 36px;
    display: flex;
    align-items: center;
  }

  .transcript-line {
    display: flex;
    align-items: flex-start;
    position: relative;
    font-size: 15px;
  }

  .line-number {
    display: inline-flex;
    justify-content: flex-end;
    width: 65px;
    min-width: 65px;
    padding: 0 6px;
    text-align: right;
    user-select: none;
    letter-spacing: -0.3px;
    background: #f5f5f5;
    margin-right: 12px;
    flex-shrink: 0;
  }

  .timestamp {
    white-space: nowrap;
    padding: 0 6px;
    width: 75px;
    min-width: 75px;
    font-size: 12px;
    user-select: none;
    overflow: hidden;
    letter-spacing: -0.3px;
    flex-shrink: 0;
  }

  .line-text {
    flex: 1;
    text-align: left;
    white-space: pre-wrap;
    word-break: break-word;
    user-select: text;
    cursor: text;
  }

  .question-block .line-text,
  .is-bold .line-text {
    font-weight: bold;
  }

  .parenthetical .line-text {
    padding-left: 2em;
    font-style: italic;
  }

  .highlighted {
    background-color: var(--highlightcolor, #ffff00);
  }

  .transcript-link {
    color: #2563eb;
    text-decoration: underline;
    cursor: pointer;
  }

  .transcript-link:hover {
    color: #1d4ed8;
  }

  @media print {
    .transcript-page {
      padding: 0;
      min-width: unset;
      width: 100%;
    }

    .transcript-page-header {
      background: #737373 !important;
      color: #fff !important;
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }

    .line-number {
      background: #f5f5f5 !important;
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
  }
`;
